def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2
    if count == 0:
        return None
    average = (v1 + v2) / count
    return {
        "value": average,
        "trace": {
            "values": [v1, v2],
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
